diff --git a/cmd/entire/cli/agent/pi/lifecycle_test.go b/cmd/entire/cli/agent/pi/lifecycle_test.go
index 8a5a8a7a..b8f2ed22 100644
--- a/cmd/entire/cli/agent/pi/lifecycle_test.go
+++ b/cmd/entire/cli/agent/pi/lifecycle_test.go
@@ -344,3 +344,97 @@ func TestPiAgent_ContextInjector(t *testing.T) {
 		t.Errorf("empty text must render no payload, got %q", string(out))
 	}
 }
+
+// TestParseHookEvent_SessionlessPayloadIsSkipped pins the guard that keeps a
+// sessionless payload from being resolved against the per-repo session-ID cache.
+//
+// A Pi subagent is a nested `pi --no-session` process that auto-discovers the same
+// project-local extension, so it fires these hooks carrying no session identity.
+// Resolving that against the single-slot cache handed the child its parent's ID,
+// and the nested turn then overwrote the parent's prompt and turn window.
+func TestParseHookEvent_SessionlessPayloadIsSkipped(t *testing.T) {
+	// Cannot use t.Parallel — t.Chdir.
+	t.Chdir(t.TempDir())
+
+	ctx := context.Background()
+	a := &PiAgent{}
+
+	// A parent session populates the cache, so a leaked ID would be observable.
+	if _, err := a.ParseHookEvent(ctx, HookNameSessionStart, strings.NewReader(
+		`{"type":"session_start","session_file":"/tmp/2026-05-09T12-00-00-000Z_parent-id.jsonl"}`)); err != nil {
+		t.Fatalf("parent session_start: %v", err)
+	}
+	if got := readCachedSessionID(ctx); got != "parent-id" {
+		t.Fatalf("cache = %q, want parent-id", got)
+	}
+
+	tests := []struct {
+		name          string
+		hook          string
+		stdin         string
+		wantSessionID string // "" means: expect no event at all
+	}{
+		{
+			name:  "nested session_start",
+			hook:  HookNameSessionStart,
+			stdin: `{"type":"session_start","cwd":"/repo"}`,
+		},
+		{
+			name:  "nested before_agent_start",
+			hook:  HookNameBeforeAgentStart,
+			stdin: `{"type":"before_agent_start","cwd":"/repo","prompt":"Task: create docs/red.md"}`,
+		},
+		{
+			name:  "nested agent_end",
+			hook:  HookNameAgentEnd,
+			stdin: `{"type":"agent_end","cwd":"/repo"}`,
+		},
+		{
+			// A session file whose basename carries no ID (trailing separator)
+			// also yields no session ID. Skipping is the safe reading: the
+			// alternative — requiring an empty session_file too — would let this
+			// payload fall through to the cache, which is the leak itself.
+			name:  "session file with unparseable name",
+			hook:  HookNameBeforeAgentStart,
+			stdin: `{"type":"before_agent_start","cwd":"/repo","session_file":"/tmp/x_.jsonl","prompt":"hi"}`,
+		},
+		{
+			// The guard distrusts a missing ID, not the payload: an explicit
+			// session_id is still honoured with no session file present.
+			name:          "explicit session_id without a session file",
+			hook:          HookNameBeforeAgentStart,
+			stdin:         `{"type":"before_agent_start","cwd":"/repo","session_id":"explicit-id","prompt":"hi"}`,
+			wantSessionID: "explicit-id",
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			cacheBefore := readCachedSessionID(ctx)
+
+			ev, err := a.ParseHookEvent(ctx, tt.hook, strings.NewReader(tt.stdin))
+			if err != nil {
+				t.Fatalf("ParseHookEvent(%s): %v", tt.hook, err)
+			}
+
+			if tt.wantSessionID == "" {
+				if ev != nil {
+					t.Fatalf("emitted %s for session %q; want no event so the cached session is left alone",
+						ev.Type, ev.SessionID)
+				}
+				// A skipped invocation must not disturb the cached session either.
+				if got := readCachedSessionID(ctx); got != cacheBefore {
+					t.Errorf("cache = %q after a skipped invocation, want %q", got, cacheBefore)
+				}
+				return
+			}
+
+			if ev == nil {
+				t.Fatalf("emitted no event; want one for session %q", tt.wantSessionID)
+			}
+			if ev.SessionID != tt.wantSessionID {
+				t.Errorf("SessionID = %q, want %q", ev.SessionID, tt.wantSessionID)
+			}
+		})
+	}
+}
diff --git a/docs/architecture/agent-guide.md b/docs/architecture/agent-guide.md
index e419f230..fb201f16 100644
--- a/docs/architecture/agent-guide.md
+++ b/docs/architecture/agent-guide.md
@@ -734,10 +734,33 @@ Pi extension hooks fire via `execFile` (non-blocking) to avoid blocking the agen
 Key differences from JSON config agents:
 - Extension file is written/removed entirely (not partial JSON edits)
 - Uses `node:child_process.execFile` for all hook invocations
-- Session ID is cached to `.entire/tmp/pi/pi-active-session` to bridge races between `session_start` and `before_agent_start`/`agent_end`
+- Session ID is written to `.entire/tmp/pi/pi-active-session` at `session_start` / `before_agent_start` and cleared at `session_shutdown`. It was meant to bridge races where a later hook arrives without an ID, but nothing reads it any more — see the nesting note below
 - On `agent_end`, the Pi JSONL transcript is captured to `.entire/tmp/pi/<id>.json` for stable reference even if native Pi sessions are deleted
 - `session_shutdown` is cleanup-only (no `SessionEnd` event) to avoid a race with `agent_end`'s checkpoint save
 - Idempotency via marker string check: `"Auto-generated by \`entire enable --agent pi\`"`
+- **Nested Pi processes do not forward session lifecycle.** Pi has no subagent
+  events; subagents come from an extension (Pi's `subagent/` example) that spawns
+  `pi --mode json -p --no-session` with cwd inside the project — where Pi
+  auto-discovers this same extension, so the child would otherwise forward its own
+  lifecycle as the user's session. Two independent guards:
+
+  1. **Extension**: sets `ENTIRE_PI_NESTED` on its process (inherited by any Pi it
+     spawns) and, when it is already set, registers only the `tool_call` bash
+     hardening and skips the lifecycle handlers. The hardening stays on purpose — a
+     nested Pi is non-interactive while inheriting the parent's TTY, and Entire's git
+     hooks fire from `.git/hooks` regardless of this extension. The marker is read
+     **only** here: Entire's own hook subprocesses inherit it from the parent, so
+     treating it as a skip signal in Go would disable tracking for everyone.
+  2. **CLI**: `ParseHookEvent` skips any hook whose payload carries no resolvable
+     session ID, rather than resolving it against the per-repo session-ID cache —
+     that single-slot cache is what handed a sessionless child its *parent's* ID,
+     letting the nested turn overwrite the parent's prompt and turn window.
+     `session_shutdown` is exempt (it carries no session identity at all and must
+     still clear the cache). Same shape as Copilot CLI's subordinate-session guard.
+
+  The guard removed the cache's only two readers, so it is now write-only; removing
+  it outright is a follow-up, tracked with the separate problem that a single-slot
+  per-repo store cannot represent two concurrent Pi sessions in one worktree.

 See `cmd/entire/cli/agent/pi/entire_extension.ts` for the full extension source.

